const SIGNALS = { SIGHUP: 1, SIGINT: 2, SIGKILL: 9, SIGTERM: 15 };

function describeExit(code, signal) {
  if (signal !== null) return `killed by ${signal} (shell reports ${128 + SIGNALS[signal]})`;
  return `exited with code ${code}`;
}

console.log(describeExit(0, null));
console.log(describeExit(1, null));
console.log(describeExit(null, "SIGTERM"));
