function createShutdown() {
  let shuttingDown = false;
  return (name) => {
    if (shuttingDown) return `force: ${name}`;
    shuttingDown = true;
    return `graceful: ${name}`;
  };
}

const onSignal = createShutdown();
console.log(onSignal("SIGTERM"));
console.log(onSignal("SIGINT"));
console.log(onSignal("SIGINT"));

const other = createShutdown();
console.log(other("SIGINT"));

