function invoiceArgs(invoice) {
  if (!Number.isInteger(invoice.amount) || invoice.amount <= 0) throw new Error("bad amount");
  const args = ["--id", invoice.id, "--amount", String(invoice.amount)];
  if (invoice.name !== undefined) args.push("--name", invoice.name);
  return args;
}

console.log(JSON.stringify(invoiceArgs({ id: "INV-1", amount: 4500000, name: 'Ada"; rm -rf ~' })));
try {
